WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT order_id, SUM(CASE WHEN status = 'REFUNDED' THEN amount ELSE 0 END) AS refunded_amount, PERCENTILE_APPROX(island_id, 0.9) AS island_id_p90, COUNT(CASE WHEN method = 'cash' THEN 1 END) AS cash_count, APPROX_PERCENTILE(island_id, 0.9) AS island_id_p90_2 FROM islands GROUP BY order_id ORDER BY island_id_p90_2 DESC;
